import random
import struct
from typing import List

# Data type: arbitrary byte buffer with width alignment (2 or 4 bytes)
# Used by wide-character APIs which only require that the buffer length is a
# positive multiple of the chosen element width; contents can be any bytes.
# The fuzzing stubs cap consumption at 2048 bytes, but FUZZ_PARAM_STR may be
# longer; we keep outputs <= 2048 and interesting across calls.

# We aim to generate inputs that are valid and exercise different behaviors:
# - Various lengths (1..2048) but rounded to multiples of 2 or 4
# - Sometimes include valid UTF-16/UTF-32 sequences (ASCII/letters/digits)
# - Sometimes include zero-terminated sequences and embedded NULs
# - Include mixed ranges, surrogate-like values, BMP/out-of-BMP code points
# - Sometimes repeat patterns to test dictionary lookups and suggestion paths
# - Sometimes craft two buffers concatenated for replacement APIs (stubs call
#   FUZZ_PARAM_STR twice independently; we just provide one buffer, but the
#   framework will call us again, so we vary content per call via seed)

MAX_BYTES = 2048

ASCII_WORDS = [
    "hello", "world", "spell", "checker", "aspell", "fuzz", "test",
    "dictionary", "language", "keyboard", "encode", "decode",
    "colour", "color", "theatre", "theater", "centre", "center",
    "teh", "recieve", "seperate", "occured", "acommodate"
]

UNICODE_WORDS = [
    "café", "naïve", "résumé", "façade", "über",
    "mañana", "東京", "Москва", "ελληνικά", "हिन्दी",
    "😀", "👍🏽", "🧪", "straße", "coöperate", "São Paulo",
]


def _rand_choice(r: random.Random, items: List[str]) -> str:
    return items[r.randrange(len(items))]


def _encode_units(r: random.Random, w: int, text: str) -> bytes:
    # Encode text into bytes of width w using UTF-16LE or UTF-32LE to fit size/width.
    if w == 2:
        return text.encode('utf-16le', errors='surrogatepass')
    else:
        return text.encode('utf-32le', errors='surrogatepass')


def _gen_textual_sequence(r: random.Random, w: int, target_bytes: int) -> bytes:
    # Build a sequence concatenating words and separators to reach target_bytes
    parts: List[bytes] = []
    while True:
        if r.random() < 0.6:
            word = _rand_choice(r, ASCII_WORDS)
        else:
            word = _rand_choice(r, UNICODE_WORDS)
        b = _encode_units(r, w, word)
        parts.append(b)
        # optional separator space or punctuation
        if r.random() < 0.7:
            parts.append(_encode_units(r, w, " "))
        if sum(len(p) for p in parts) >= target_bytes:
            break
    data = b"".join(parts)
    # Trim to multiple of w not exceeding target_bytes
    data = data[: target_bytes - (target_bytes % w)]
    if not data:
        data = _encode_units(r, w, "a")
    return data


def _gen_pattern_bytes(r: random.Random, w: int, elems: int) -> bytes:
    # Generate structured binary patterns aligned to width
    out = bytearray()
    if w == 2:
        for _ in range(elems):
            mode = r.randrange(5)
            if mode == 0:
                # ASCII letter
                out += struct.pack('<H', r.randrange(0x41, 0x5B))
            elif mode == 1:
                # digit
                out += struct.pack('<H', r.randrange(0x30, 0x3A))
            elif mode == 2:
                # space or punctuation
                out += struct.pack('<H', r.choice([0x20, 0x2D, 0x27, 0x2C, 0x2E]))
            elif mode == 3:
                # surrogate range value (not text, but valid 16-bit unit)
                out += struct.pack('<H', r.randrange(0xD800, 0xE000))
            else:
                # random BMP
                out += struct.pack('<H', r.randrange(0x0000, 0xFFFE))
    else:
        for _ in range(elems):
            mode = r.randrange(5)
            if mode == 0:
                cp = r.randrange(0x41, 0x5B)  # ASCII uppercase
            elif mode == 1:
                cp = r.randrange(0x1F600, 0x1F64F)  # emoji block subset
            elif mode == 2:
                cp = r.randrange(0x0400, 0x04FF)  # Cyrillic
            elif mode == 3:
                cp = 0  # NUL to test embedded zeros
            else:
                cp = r.randrange(0x0000, 0x10FFFF)
            out += struct.pack('<I', cp)
    return bytes(out)


def _maybe_zero_terminate(r: random.Random, w: int, data: bytes) -> bytes:
    # Occasionally append a code-unit NUL terminator (not required by API, but common)
    if r.random() < 0.4:
        if w == 2:
            term = b"\x00\x00"
        else:
            term = b"\x00\x00\x00\x00"
        data = data + term
    return data


def _bounded_aligned_length(r: random.Random, w: int) -> int:
    # Choose an aligned byte length in [w, MAX_BYTES], bias to small and also some larger sizes
    if r.random() < 0.6:
        elems = r.randint(1, 16)
    elif r.random() < 0.85:
        elems = r.randint(17, 128)
    else:
        # occasionally bigger
        max_elems = MAX_BYTES // w
        elems = r.randint(129, max(130, max_elems))
    length = min(MAX_BYTES, elems * w)
    return max(w, length - (length % w))


