        remaining = target_len - (len(base) - (len(base) % w))
        if remaining < 0:
            remaining = 0
        pad = _gen_pattern_bytes(r, w, remaining // w)
        data = (base[: target_len - (target_len % w)]) + pad
        data = data[: target_len - (target_len % w)]

    data = data[:MAX_BYTES]
    data = _maybe_zero_terminate(r, w, data)

    # Ensure non-empty and aligned, within bounds
    if not data:
        data = b"\x00\x00" if w == 2 else b"\x00\x00\x00\x00"
    if len(data) % w != 0:
        # pad with zeros to the next multiple
        pad_len = (-len(data)) % w
        data += b"\x00" * pad_len
    if len(data) > MAX_BYTES:
        # trim to MAX_BYTES while keeping alignment
        data = data[: MAX_BYTES - (MAX_BYTES % w)]
        if not data:
            data = b"\x00\x00" if w == 2 else b"\x00\x00\x00\x00"

    return data
